<template><view class="training-page"><NativeStatusSpacer/><view class="topbar"><button @tap="back">‹</button><text>培训项目与申请</text><view/></view><view class="paper"><view v-if="loading" class="state">正在加载</view><view v-if="error" class="state error"><text>{{error}}</text><button v-if="!busy" @tap="initialize">重新加载</button></view>
<template v-if="canRegister"><view class="card"><text class="title">显式登记培训项目</text><text class="muted">仅登记的班级会作为培训项目展示。</text><picker :range="classLabels" :value="classIndex" :disabled="busy" @change="chooseClass"><view class="picker">{{classLabels[classIndex]}} ⌄</view></picker><button v-if="candidateHasMore" :disabled="candidateLoading||busy" @tap="loadClasses()">{{candidateLoading?'正在加载':'加载更多可登记班级'}}</button><picker :range="typeLabels" :value="typeIndex" :disabled="busy" @change="chooseType"><view class="picker">{{typeLabels[typeIndex]}} ⌄</view></picker><picker :range="['开放报名','停止报名']" :value="enrollable==='ENABLED'?0:1" :disabled="busy" @change="chooseEnrollable"><view class="picker">{{enrollable==='ENABLED'?'开放报名':'停止报名'}} ⌄</view></picker><button class="primary" :disabled="busy||!programId" @tap="saveProgram">{{busy?'正在处理…':'保存项目登记'}}</button></view><view class="card"><text class="title">已登记项目</text><view v-for="item in registrations.items" :key="item.programOrganizationId" class="row" @tap="editProgram(item)"><text>{{item.programName}}</text><text class="muted">{{item.programType==='OFFICIAL_COURSE'?'正式课程':'社团活动'}} · {{item.enrollable==='ENABLED'?'开放报名':'停止报名'}}</text><text class="edit">修改登记 ›</text></view><view v-if="registrations.loading" class="state">正在加载项目</view><view v-else-if="registrations.error" class="state error"><text>{{registrations.error}}</text><button @tap="loadRegistrations">重试</button></view><view v-else-if="!registrations.items.length" class="state">暂无已登记培训项目</view><view v-else-if="!registrations.hasMore" class="state">已加载全部项目</view></view></template>
<view v-if="canReview" class="card"><text class="title">培训申请审核</text><textarea v-model="reviewReason" maxlength="200" :disabled="busy" placeholder="审核说明（最多200字，驳回必填）"/><text class="muted count">{{reviewReason.length}}/200</text><view v-for="item in requests.items" :key="item.id" class="row"><text>{{item.studentName}} · {{item.programName}}</text><text class="muted">{{trainingStatusLabel[item.status]}} · {{item.createdAt}}</text><text v-if="item.reason" class="muted">申请说明：{{item.reason}}</text><text v-if="item.reviewReason" class="muted">审核说明：{{item.reviewReason}}</text><view v-if="item.status==='PENDING'" class="actions"><button :disabled="busy" @tap="reviewRequest(item,'reject')">驳回</button><button class="primary" :disabled="busy" @tap="reviewRequest(item,'approve')">通过</button></view></view><view v-if="requests.loading" class="state">正在加载申请</view><view v-else-if="requests.error" class="state error"><text>{{requests.error}}</text><button @tap="loadRequests">重试</button></view><view v-else-if="!requests.items.length" class="state">暂无培训申请</view><view v-else-if="!requests.hasMore" class="state">已加载全部申请</view></view>
</view></view></template>
<script setup lang="ts">
import {ref,computed} from 'vue';
import {onShow,onHide,onUnload,onReachBottom} from '@dcloudio/uni-app';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import {trainingApi,trainingStatusLabel,type TrainingProgram,type TrainingRequest,type TrainingType} from '@/api/training';
interface ProgramCandidate{id:string;name:string}
import {request} from '@/api/http';
import {getMiniappCapabilities} from '@/api/capability';
import {getOrganizationSession} from '@/session/organization-session';
const REGISTER='STUDENT_TRAINING_PROGRAM_MANAGE',REVIEW='STUDENT_TRAINING_REQUEST_REVIEW';
interface Pager<T>{items:T[];page:number;hasMore:boolean;loading:boolean;error:string}
function empty<T>():Pager<T>{return {items:[],page:0,hasMore:true,loading:false,error:''};}
const registrations=ref<Pager<TrainingProgram>>(empty()),requests=ref<Pager<TrainingRequest>>(empty()),classes=ref<ProgramCandidate[]>([]),canRegister=ref(false),canReview=ref(false),programId=ref(''),programType=ref<TrainingType>('OFFICIAL_COURSE'),enrollable=ref<'ENABLED'|'DISABLED'>('ENABLED'),reviewReason=ref(''),loading=ref(false),busy=ref(false),error=ref('');
const types:TrainingType[]=['OFFICIAL_COURSE','CLUB_ACTIVITY'],typeLabels=['正式课程','社团活动'],typeIndex=computed(()=>Math.max(0,types.indexOf(programType.value))),classLabels=computed(()=>['请选择本机构班级',...classes.value.map(c=>c.name)]),classIndex=computed(()=>Math.max(0,classes.value.findIndex(c=>c.id===programId.value)+1));
const candidateLoading=ref(false),candidateHasMore=ref(true);let candidatePage=0;
let token='',institutionId='',visible=false,revision=0;
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function scope(){const s=selection();return !!token&&getOrganizationSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===institutionId&&['SCHOOL','TRAINING_INSTITUTION'].includes(s.typeCode||'');}
function current(n:number){return visible&&n===revision&&scope();}
async function access(n:number,permission?:string){const [me,cap]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),getMiniappCapabilities()]);if(!current(n))return null;if(cap.studentOrganizationRelationshipEnabled!==true)throw Error('学员组织关系功能未启用');if(permission&&!me.permissionCodes.includes(permission))throw Error('当前账号没有此操作权限');return me.permissionCodes;}

async function initialize(){visible=true;const n=++revision;token=getOrganizationSession()?.accessToken||'';institutionId=selection()?.organizationId||'';registrations.value=empty();requests.value=empty();classes.value=[];programId.value='';reviewReason.value='';canRegister.value=false;canReview.value=false;busy.value=false;loading.value=true;error.value='';candidatePage=0;candidateLoading.value=false;candidateHasMore.value=true;if(!scope()){error.value='请先选择学校或培训机构';loading.value=false;return;}try{const permissions=await access(n);if(!permissions)return;canRegister.value=permissions.includes(REGISTER);canReview.value=permissions.includes(REVIEW);if(!canRegister.value&&!canReview.value)throw Error('当前账号没有培训管理权限');const work:Promise<unknown>[]=[];if(canRegister.value){work.push(loadRegistrations());work.push(loadClasses(n));}if(canReview.value)work.push(loadRequests());await Promise.all(work);}catch(e){if(current(n))error.value=e instanceof Error?e.message:'加载失败';}finally{if(current(n))loading.value=false;}}
async function loadClasses(n=revision){if(!current(n)||!canRegister.value||candidateLoading.value||!candidateHasMore.value)return;candidateLoading.value=true;try{const result=await trainingApi.candidates(token,institutionId,candidatePage+1);if(!current(n))return;const seen=new Set(classes.value.map(c=>c.id));classes.value.push(...result.items.filter(c=>!seen.has(c.programOrganizationId)&&!!seen.add(c.programOrganizationId)).map(c=>({id:c.programOrganizationId,name:c.programName})));candidatePage=result.page;candidateHasMore.value=result.items.length>0&&result.page*result.pageSize<result.total;}catch(e){if(current(n))error.value=e instanceof Error?e.message:'候选项目加载失败';}finally{if(current(n))candidateLoading.value=false;}}
async function loadRegistrations(){await loadPage('registrations');}
async function loadRequests(){await loadPage('requests');}
async function loadPage(kind:'registrations'|'requests'){const holder=kind==='registrations'?registrations:requests;if(!current(revision)||(kind==='registrations'?!canRegister.value:!canReview.value)||holder.value.loading||!holder.value.hasMore)return;const n=revision,next=holder.value.page+1;holder.value.loading=true;holder.value.error='';try{if(kind==='registrations'){const result=await trainingApi.registrations(token,institutionId,next);if(!current(n))return;const seen=new Set(registrations.value.items.map(p=>p.programOrganizationId));registrations.value.items=[...registrations.value.items,...result.items.filter(p=>p.institutionOrganizationId===institutionId&&!seen.has(p.programOrganizationId)&&!!seen.add(p.programOrganizationId))];registrations.value.page=next;registrations.value.hasMore=result.items.length>0&&next*Math.max(1,result.pageSize||20)<result.total;}else{const result=await trainingApi.requests(token,{institutionOrganizationId:institutionId},next);if(!current(n))return;const seen=new Set(requests.value.items.map(p=>p.id));requests.value.items=[...requests.value.items,...result.items.filter(p=>p.institutionOrganizationId===institutionId&&!seen.has(p.id)&&!!seen.add(p.id))];requests.value.page=next;requests.value.hasMore=result.items.length>0&&next*Math.max(1,result.pageSize||20)<result.total;}}catch(e){if(current(n))holder.value.error=e instanceof Error?e.message:'加载失败';}finally{if(current(n))holder.value.loading=false;}}
function chooseClass(e:{detail:{value:string}}){if(!busy.value)programId.value=classes.value[Number(e.detail.value)-1]?.id||'';}
function chooseType(e:{detail:{value:string}}){if(!busy.value)programType.value=types[Number(e.detail.value)]||'OFFICIAL_COURSE';}
function chooseEnrollable(e:{detail:{value:string}}){if(!busy.value)enrollable.value=Number(e.detail.value)===0?'ENABLED':'DISABLED';}
function editProgram(item:TrainingProgram){if(!current(revision)||busy.value||!canRegister.value||item.institutionOrganizationId!==institutionId||!registrations.value.items.some(p=>p.programOrganizationId===item.programOrganizationId))return;if(!classes.value.some(c=>c.id===item.programOrganizationId))classes.value.push({id:item.programOrganizationId,name:item.programName});programId.value=item.programOrganizationId;programType.value=item.programType;enrollable.value=item.enrollable;}
function confirmWrite(n:number,title:string,content:string,write:()=>Promise<void>){let settled=false;uni.showModal({title,content,confirmText:'确认',success:r=>{if(!current(n)||settled)return;settled=true;if(!r.confirm){busy.value=false;return;}void(async()=>{try{await write();}catch(e){if(current(n))error.value=e instanceof Error?e.message:'操作失败，请重新确认';}finally{if(current(n))busy.value=false;}})();},fail:()=>{if(current(n)){busy.value=false;error.value='确认未完成，请重试';}}});}
async function saveProgram(){if(!current(revision)||busy.value||!canRegister.value)return;const n=revision,id=programId.value,type=programType.value,state=enrollable.value;if(!id||!types.includes(type)||!['ENABLED','DISABLED'].includes(state)){error.value='请选择本机构班级、课程类型及报名状态';return;}busy.value=true;error.value='';try{if(!await access(n,REGISTER))return;if(!current(n))return;const selected=classes.value.find(c=>c.id===id);if(!selected)throw Error('该班级不属于当前机构或已不可管理');confirmWrite(n,'确认项目登记',`${selected.name} · ${type==='OFFICIAL_COURSE'?'正式课程':'社团活动'} · ${state==='ENABLED'?'开放报名':'停止报名'}`,async()=>{if(!current(n)||!await access(n,REGISTER))return;const result=await trainingApi.register(token,id,{institutionOrganizationId:institutionId,programType:type,enrollable:state});if(!current(n))return;if(result.institutionOrganizationId!==institutionId)throw Error('项目机构范围不匹配');const index=registrations.value.items.findIndex(p=>p.programOrganizationId===id);if(index>=0)registrations.value.items=registrations.value.items.map(p=>p.programOrganizationId===id?result:p);else registrations.value.items=[result,...registrations.value.items];});}catch(e){if(current(n)){busy.value=false;error.value=e instanceof Error?e.message:'登记失败';}}}
async function reviewRequest(item:TrainingRequest,decision:'approve'|'reject'){if(!current(revision)||busy.value||!canReview.value||item.institutionOrganizationId!==institutionId||item.status!=='PENDING'||!requests.value.items.some(r=>r.id===item.id))return;const reason=reviewReason.value.trim();if(reason.length>200||(decision==='reject'&&!reason)){error.value='驳回请填写审核原因，最多200字';return;}const n=revision;busy.value=true;error.value='';try{if(!await access(n,REVIEW))return;const latest=await trainingApi.detail(token,item.id);if(!current(n))return;if(latest.institutionOrganizationId!==institutionId||latest.status!=='PENDING')throw Error('申请机构或状态已变化，请重新加载');confirmWrite(n,decision==='approve'?'确认通过申请':'确认驳回申请',`${latest.studentName} · ${latest.programName}`,async()=>{if(!current(n)||!await access(n,REVIEW))return;const result=await trainingApi.review(token,item.id,decision,reason);if(!current(n))return;if(result.institutionOrganizationId!==institutionId)throw Error('申请机构范围不匹配');requests.value.items=requests.value.items.map(r=>r.id===result.id?result:r);reviewReason.value='';});}catch(e){if(current(n)){busy.value=false;error.value=e instanceof Error?e.message:'审核失败';}}}
function hide(){visible=false;++revision;candidateLoading.value=false;candidateHasMore.value=false;candidatePage=0;registrations.value=empty();requests.value=empty();classes.value=[];canRegister.value=false;canReview.value=false;busy.value=false;loading.value=false;error.value='';}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/organization-home/organization-home'})});}
onShow(initialize);onHide(hide);onUnload(hide);onReachBottom(()=>{if(!registrations.value.error)void loadRegistrations();if(!requests.value.error)void loadRequests();});
</script>
<style scoped>
.training-page{min-height:100vh;background:#17684f;color:#214432}.topbar{height:86rpx;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;color:#fff;font-size:32rpx;font-weight:650}.topbar button{margin:0;padding:0;background:transparent;color:white;font-size:48rpx;width:48rpx;line-height:72rpx}.topbar>view{width:48rpx}.paper{min-height:calc(100vh - 130rpx);padding:30rpx 24rpx 70rpx;box-sizing:border-box;border-radius:30rpx 30rpx 0 0;background:#f8faf5}.card{padding:26rpx;background:#fffef9;border:1rpx solid #e5ebdf;border-radius:24rpx;margin-bottom:22rpx;font-size:28rpx}.title{display:block;font-size:30rpx;font-weight:650;margin-bottom:20rpx}.muted{display:block;font-size:23rpx;color:#87917f;line-height:1.7}.picker{background:#f2f5ec;border-radius:14rpx;padding:22rpx;font-size:27rpx;margin:18rpx 0}textarea{width:100%;height:140rpx;font-size:26rpx;background:#f7f8f2;padding:18rpx;box-sizing:border-box;border-radius:14rpx}.count{text-align:right}.primary{background:#17764f;color:white}.state{display:flex;flex-direction:column;gap:16rpx;padding:24rpx;font-size:25rpx;color:#85917d}.error{color:#ad5e49}.row{padding:22rpx 0;border-top:1rpx solid #e8eee1;overflow-wrap:anywhere}.actions{display:flex;gap:20rpx;margin-top:18rpx}.actions button{flex:1}.edit{display:block;color:#277a51;font-size:24rpx;margin-top:12rpx}button{font-size:26rpx;border-radius:16rpx;padding:16rpx;color:#24603d;background:#e6efe0}button::after{border:0}
</style>

